import React, { useEffect, useMemo, useState } from 'react';
import {
 Activity, HeartPulse, Brain, CalendarDays, ShieldAlert, MessageCircle, LayoutDashboard,
 UserRound, LogOut, Menu, Stethoscope, FileText, ChevronRight, Plus, Download, Send,
 Wind, CheckCircle2, Trash2, Sparkles, ArrowRight, RotateCcw, Info, Phone, X,
 ClipboardList, Copy, Moon, Sun
} from 'lucide-react';
import { api, setSession, clearSession, downloadAttachment } from './services/api';

const DEMO_USER={id:'demo-user',full_name:'Aarav Demo',email:'demo@medivision.local',age:27,age_group:'16-30',gender:'Prefer not to say',health_goal:'fitness',women_health_opt_in:true,privacy_consent:false};
const STORE='mv_demo_data_v2', USER_STORE='mv_demo_user';
const seed={
 wellnessEntries:[
  {id:'demo-w3',mood:'Normal',sleep_hours:7.5,stress_score:19,note:'A steady day. Took a short walk after lunch.',created_at:'2026-11-06T08:30:00.000Z'},
  {id:'demo-w2',mood:'Stressed',sleep_hours:6,stress_score:51,note:'Long study session and too much screen time.',created_at:'2026-11-05T08:30:00.000Z'},
  {id:'demo-w1',mood:'Happy',sleep_hours:8,stress_score:5,note:'Restful night and a light workout.',created_at:'2026-11-03T08:30:00.000Z'}
 ],
 healthChecks:[
  {id:'demo-h3',symptoms:'Example note: mild neck stiffness after sitting at a desk for several hours.',category:'symptom-check',severity:'Needs review',guidance:'Sample entry for record-keeping only. This tool does not identify a disease or determine clinical severity.',created_at:'2026-11-06T10:00:00.000Z'},
  {id:'demo-h2',symptoms:'Example note: seasonal sneezing and itchy eyes after spending time outdoors.',category:'symptom-check',severity:'Needs review',guidance:'This example does not identify a cause. Discuss persistent or concerning symptoms with a qualified healthcare professional.',created_at:'2026-11-04T09:00:00.000Z'},
  {id:'demo-h1',symptoms:'Example note: saved a sample report note to practise organizing health information.',category:'report',severity:'Information',guidance:'Sample report record only. No medical report interpretation is performed.',created_at:'2026-11-02T09:00:00.000Z'}
 ],
 cycleEntries:[
  {id:'demo-c2',start_date:'2026-10-10',cycle_length:29,notes:'Fictional sample cycle entry.'},
  {id:'demo-c1',start_date:'2026-09-11',cycle_length:29,notes:'Fictional sample cycle entry.'}
 ],
 contacts:[{id:'demo-contact-1',name:'Demo emergency contact',relationship:'Example only',phone:'00000 00000'}]
};
function loadDemo(){try{const d=JSON.parse(localStorage.getItem(STORE));if(d&&Array.isArray(d.wellnessEntries)&&Array.isArray(d.healthChecks))return {...seed,...d};}catch{}return seed;}
function makeId(){return 'demo-'+Date.now()+'-'+Math.random().toString(16).slice(2,7);}
function dateLabel(v){return v?new Date(v).toLocaleDateString(undefined,{day:'numeric',month:'short'}):'';}
const nav=[
 ['Overview',LayoutDashboard],['Health check',Stethoscope],['Wellness',Brain],['Age guidance',Activity],
 ["Women's health",HeartPulse],['Emergency',ShieldAlert],['AI assistant',MessageCircle],['My records',FileText],['Profile',UserRound]
];
const prompts=['How can I build a healthier sleep routine?','Suggest a simple desk-break routine.','What are grounding techniques for stress?','When should I seek urgent medical help?'];
const guides={
 '16-30':{title:'Build strong foundations',items:['Mix enjoyable walking, cycling or other activities with age-appropriate strength work.','Take short movement breaks during long study or screen sessions.','Keep a consistent sleep routine and make time for recovery.','Start gradually and avoid exercising through pain.'],routine:['5-minute easy warm-up','10-minute comfortable walk','Gentle shoulder and neck mobility','Cool down and hydrate']},
 '30-45':{title:'Balance work and wellbeing',items:['Break up long sitting periods with short movement breaks.','Try gentle neck, shoulder, back and eye-rest routines.','Make time for regular activity, recovery and sleep.','Track health measurements with clinician guidance when appropriate.'],routine:['Stand and stretch between work blocks','Take a comfortable 10-minute walk','Rest your eyes and adjust screen position','Finish with gentle breathing']},
 '45+':{title:'Move steadily and safely',items:['Choose comfortable walking, balance and mobility activities.','Begin at a manageable level and increase gradually.','Use support or supervision if balance is uncertain.','Ask a clinician about activity changes if you have chronic conditions or new symptoms.'],routine:['Begin with supported gentle movement','Walk at a comfortable pace if appropriate','Include balance only with stable support','Stop if pain, dizziness or unusual breathlessness occurs']}
};
function Notice({children,tone='info'}){return <div className={'notice '+tone}>{children}</div>;}
function Panel({title,subtitle,action,children,className=''}){return <section className={'panel '+className}><div className="panel-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section>;}
function Btn({children,kind='primary',...props}){return <button className={'btn '+kind} {...props}>{children}</button>;}
function Empty({children='Nothing saved here yet.'}){return <div className="empty"><Sparkles size={20}/><span>{children}</span></div>;}
function Field({label,hint,children}){return <label className="field"><span className="field-label">{label}</span>{children}{hint&&<small className="field-hint">{hint}</small>}</label>;}
function Suggestions({items,onPick}){return <div className="suggestion-row">{items.map((x,i)=><button type="button" key={i} onClick={()=>onPick(x)}>{x}</button>)}</div>;}
function Stat({icon:Icon,label,value,sub}){return <div className="stat-card"><div className="stat-icon"><Icon size={19}/></div><span>{label}</span><b>{value}</b><small>{sub}</small></div>;}
function SparkLine({values=[]}){const vals=values.length?values:[0,0,0],max=Math.max(10,...vals),min=Math.min(0,...vals);const coords=vals.map((v,i)=>(vals.length===1?50:i*100/(vals.length-1))+','+(38-((v-min)/(max-min||1))*30)).join(' ');return <svg className="sparkline" viewBox="0 0 100 42" preserveAspectRatio="none" aria-label="Illustrative trend"><polyline points={coords} fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"/>{vals.map((v,i)=><circle key={i} cx={vals.length===1?50:i*100/(vals.length-1)} cy={38-((v-min)/(max-min||1))*30} r="2.3" fill="currentColor"/>)}</svg>;}

function Auth({onAuth,onDemo,serviceStatus}){
 const initialToken=new URLSearchParams(window.location.hash.replace(/^#/, '')).get('reset_token')||new URLSearchParams(window.location.search).get('reset_token')||'';
 const [mode,setMode]=useState(()=>initialToken?'reset':'login');
 const [resetToken]=useState(initialToken);
 const [form,setForm]=useState({full_name:'',email:'',password:'',age:'',age_group:'30-45',gender:'',health_goal:'prevent',women_health_opt_in:false,privacy_consent:false});
 const [error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false);
 const change=(k,v)=>setForm(f=>({...f,[k]:v}));
 function switchMode(next){setMode(next);setError('');setNotice('');}
 async function submit(e){
  e.preventDefault();setBusy(true);setError('');setNotice('');
  try{
   if(mode==='forgot'){
    const result=await api('/api/auth/forgot-password',{method:'POST',body:JSON.stringify({email:form.email})});
    setNotice(result.message||'If an account exists for that email, a password-reset link will be sent.');
   }else if(mode==='reset'){
    const result=await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify({token:resetToken,password:form.password})});
    window.history.replaceState({},'',window.location.pathname);
    setForm(f=>({...f,password:''}));
    setNotice(result.message||'Password updated. Sign in with your new password.');
    setMode('login');
   }else{
    const result=await api('/api/auth/'+mode,{method:'POST',body:JSON.stringify({...form,age:form.age?Number(form.age):null})});
    setSession(result);onAuth(result.user);
   }
  }catch(err){setError(err.message);}finally{setBusy(false);}
 }
 const heading=mode==='register'?'Create your account':mode==='forgot'?'Reset your password':mode==='reset'?'Choose a new password':'Sign in to MediVision';
 return <div className="auth-screen">
  <div className="auth-intro"><div className="brand-mark"><HeartPulse/></div><span className="eyebrow">YOUR PERSONAL WELLNESS COMPANION</span><h1>Health, made <em>clearer.</em></h1><p>A thoughtful space to organize everyday wellness, explore health education and build healthy habits at your pace.</p><div className="auth-points"><span>✦ Guided examples</span><span>♡ Privacy-minded</span><span>⌁ Clear safety boundaries</span></div><div className="auth-preview"><div className="preview-icon"><Activity/></div><div><b>Explore before you sign up</b><small>Try every section with fictional sample data.</small></div><CheckCircle2/></div></div>
  <form className="auth-card" onSubmit={submit}>
   <span className="eyebrow">{mode==='login'?'WELCOME BACK':mode==='register'?'GET STARTED':'ACCOUNT RECOVERY'}</span>
   <h2>{heading}</h2>
   <p className="muted">{mode==='forgot'?'Enter your account email. If it matches an active account, a secure, time-limited reset link will be sent.':mode==='reset'?'Choose a new password. This link can only be used once and expires after 30 minutes.':'Use your own account for personal entries, or explore the demo without registration.'}</p>
   {mode==='register'&&<><Field label="Full name"><input required minLength="2" value={form.full_name} onChange={e=>change('full_name',e.target.value)} placeholder="e.g. Priya Sharma"/></Field><div className="field-grid"><Field label="Age (optional)"><input type="number" min="16" max="120" value={form.age} onChange={e=>change('age',e.target.value)} placeholder="e.g. 24"/></Field><Field label="Age group"><select value={form.age_group} onChange={e=>change('age_group',e.target.value)}><option>16-30</option><option>30-45</option><option>45+</option></select></Field></div><Field label="Gender (optional)"><select value={form.gender} onChange={e=>change('gender',e.target.value)}><option value="">Prefer not to say</option><option>Female</option><option>Male</option><option>Non-binary</option><option>Self describe</option></select></Field><Field label="Primary wellness goal"><select value={form.health_goal} onChange={e=>change('health_goal',e.target.value)}><option value="prevent">Preventive wellness</option><option value="fitness">Improve fitness</option><option value="stress">Reduce stress</option><option value="senior">Senior care</option></select></Field><label className="check"><input type="checkbox" checked={form.women_health_opt_in} onChange={e=>change('women_health_opt_in',e.target.checked)}/> Enable optional women's health tools</label><label className="check"><input type="checkbox" checked={form.privacy_consent} required onChange={e=>change('privacy_consent',e.target.checked)}/> I consent to saving my account and wellness entries</label></>}
   {mode!=='reset'&&<Field label="Email address"><input type="email" required value={form.email} onChange={e=>change('email',e.target.value)} placeholder="you@example.com"/></Field>}
   {(mode==='login'||mode==='register'||mode==='reset')&&<Field label={mode==='reset'?'New password':'Password'} hint="Use at least 12 characters."><input type="password" required minLength="12" value={form.password} onChange={e=>change('password',e.target.value)} placeholder={mode==='reset'?'Choose a new password':'Enter your password'}/></Field>}
   {error&&<Notice tone="error">{error}</Notice>}
   {notice&&<Notice tone="success">{notice}</Notice>}
   {(mode!=='forgot'||serviceStatus?.password_reset_email==='configured')&&<Btn disabled={busy}>{busy?'Please wait…':mode==='login'?'Sign in':mode==='register'?'Create account':mode==='forgot'?'Send reset link':'Update password'} <ChevronRight size={16}/></Btn>}
   {mode==='login'&&serviceStatus?.password_reset_email==='configured'&&<button className="text-action forgot-link" type="button" onClick={()=>switchMode('forgot')}>Forgot password?</button>}
   {mode==='login'&&serviceStatus&&serviceStatus.password_reset_email!=='configured'&&<Notice tone="warning">Email-based account recovery is not active yet. Contact the project administrator if you cannot sign in.</Notice>}
   {mode==='forgot'&&serviceStatus?.password_reset_email!=='configured'&&<Notice tone="warning">Password-reset email delivery is not configured. Contact the project administrator for account recovery.</Notice>}
   {mode!=='reset'&&mode!=='forgot'&&<button className="demo-entry" type="button" onClick={onDemo}><Sparkles size={17}/> Explore interactive demo <ArrowRight size={16}/></button>}
   {mode==='forgot'&&<p className="switch"><button type="button" onClick={()=>switchMode('login')}>Back to sign in</button></p>}
   {mode==='reset'&&<p className="switch"><button type="button" onClick={()=>{window.history.replaceState({},'',window.location.pathname);switchMode('login');}}>Back to sign in</button></p>}
   {(mode==='login'||mode==='register')&&<p className="switch">{mode==='login'?'New to MediVision?':'Already have an account?'} <button type="button" onClick={()=>switchMode(mode==='login'?'register':'login')}>{mode==='login'?'Create account':'Sign in'}</button></p>}
   <small>Educational prototype only. Not a substitute for professional medical care.</small>
  </form>
 </div>;
}

export default function App(){
 const [demoMode,setDemoMode]=useState(()=>localStorage.getItem('mv_demo')==='1');
 const [demoData,setDemoData]=useState(loadDemo);
 const [user,setUser]=useState(()=>{try{return localStorage.getItem('mv_demo')==='1'?(JSON.parse(localStorage.getItem(USER_STORE)||'null')||DEMO_USER):null;}catch{return null;}});
 const [page,setPage]=useState('Overview'),[data,setData]=useState(null),[toast,setToast]=useState(''),[mobile,setMobile]=useState(false),[loading,setLoading]=useState(false);
 const [sessionReady,setSessionReady]=useState(()=>localStorage.getItem('mv_demo')==='1');
 const [serviceStatus,setServiceStatus]=useState(null);
 useEffect(()=>{let active=true;api('/api/health').then(result=>{if(active)setServiceStatus(result.security||{});}).catch(()=>{if(active)setServiceStatus({});});return()=>{active=false;};},[]);
 useEffect(()=>{if(demoMode){setSessionReady(true);return;}let active=true;api('/api/auth/me').then(u=>{if(active)setUser(u);}).catch(()=>{if(active){clearSession();setUser(null);}}).finally(()=>{if(active)setSessionReady(true);});return()=>{active=false;};},[]);
 function notify(s){setToast(s);window.clearTimeout(window.__mvToast);window.__mvToast=window.setTimeout(()=>setToast(''),3200);}
 useEffect(()=>{localStorage.setItem(STORE,JSON.stringify(demoData));},[demoData]);
 useEffect(()=>{if(demoMode){localStorage.setItem('mv_demo','1');localStorage.setItem(USER_STORE,JSON.stringify(user||DEMO_USER));}},[demoMode,user]);
 function enterDemo(){api('/api/auth/logout',{method:'POST'}).catch(()=>{});clearSession();setDemoMode(true);let saved=null;try{saved=JSON.parse(localStorage.getItem(USER_STORE)||'null');}catch{}setUser(saved||DEMO_USER);setPage('Overview');}
 function logout(){if(!demoMode)api('/api/auth/logout',{method:'POST'}).catch(()=>{});if(demoMode){localStorage.removeItem('mv_demo');localStorage.removeItem(USER_STORE);setDemoMode(false);}clearSession();localStorage.removeItem('mv_user');setUser(null);setData(null);setPage('Overview');}
 function updateDemo(fn){setDemoData(d=>typeof fn==='function'?fn(d):fn);}
 function resetDemo(){setDemoData(seed);setUser(DEMO_USER);notify('Demo data reset to sample values');}
 const overview=useMemo(()=>({user,wellness_count:demoData.wellnessEntries.length,diagnosis_count:demoData.healthChecks.length,latest_wellness:demoData.wellnessEntries[0]||null,recent_records:demoData.healthChecks.slice(0,5),cycle_tracking_enabled:user?.women_health_opt_in,cycle_count:demoData.cycleEntries.length}),[demoData,user]);
 function pageDemoData(){if(page==='Overview'||page==='My records')return overview;if(page==='Health check')return demoData.healthChecks;if(page==='Wellness')return demoData.wellnessEntries;if(page==='Age guidance')return guides[user?.age_group]||guides['30-45'];if(page==="Women's health")return user?.women_health_opt_in?demoData.cycleEntries:{locked:true};if(page==='Emergency')return demoData.contacts;return null;}
 async function load(){if(!user||demoMode)return;const paths={'Overview':'/api/dashboard','My records':'/api/dashboard','Health check':'/api/diagnosis','Wellness':'/api/wellness','Age guidance':'/api/guidance/'+encodeURIComponent(user.age_group||'30-45'),"Women's health":'/api/womens-health/cycles','Emergency':'/api/emergency/contacts','Profile':'/api/profile'};if(!paths[page]){setData(null);return;}setLoading(true);try{setData(await api(paths[page]));}catch(e){setData(page==="Women's health"?{locked:true}:null);notify(e.message);}finally{setLoading(false);}}
 useEffect(()=>{if(!sessionReady)return;if(demoMode){setData(pageDemoData());return;}load();},[page,user,demoMode,demoData,sessionReady]);
 if(!sessionReady)return <div className="auth-screen"><div className="auth-card"><h2>Checking your secure session…</h2><p className="muted">Please wait while MediVision confirms your sign-in.</p></div></div>;
 if(!user&&!demoMode)return <Auth serviceStatus={serviceStatus} onAuth={u=>{setDemoMode(false);setUser(u);}} onDemo={enterDemo}/>;
 return <div className="app-shell">
  <aside className={'sidebar '+(mobile?'open':'')}><div className="brand"><div className="brand-mark"><HeartPulse/></div><div><b>MediVision</b><small>AI WELLNESS SPACE</small></div><button className="mobile-close" onClick={()=>setMobile(false)}><X size={17}/></button></div><span className="nav-caption">YOUR SPACE</span>
   {nav.map(([name,Icon])=><button key={name} className={'nav-item '+(page===name?'active':'')} onClick={()=>{setPage(name);setMobile(false)}}><Icon size={18}/>{name}{page===name&&<span className="nav-dot"/>}</button>)}
   <div className="sidebar-bottom"><div className="user-mini"><div className="avatar">{user?.full_name?.[0]||'U'}</div><div><b>{user?.full_name}</b><small>{demoMode?'Sample demo profile':user?.age_group+' age group'}</small></div></div>{demoMode&&<button className="logout reset" onClick={resetDemo}><RotateCcw size={15}/> Reset demo data</button>}<button className="logout" onClick={logout}><LogOut size={16}/>{demoMode?'Exit demo':'Sign out'}</button></div>
  </aside>
  <main className="main"><header className="topbar"><div className="topbar-left"><button className="mobile-menu" onClick={()=>setMobile(!mobile)}><Menu/></button><div><span className="eyebrow">YOUR WELLNESS JOURNEY</span><h1>{page}</h1></div></div><div className="top-user">{demoMode?<span className="mode-pill"><Sparkles size={13}/> DEMO DATA</span>:<span className="mode-pill live"><span className="status-dot"/> PRIVATE ACCOUNT</span>}<div className="avatar">{user?.full_name?.[0]||'U'}</div></div></header>
   {demoMode&&<div className="demo-ribbon"><Info size={15}/> Fictional sample data. Changes are saved only in this browser and are not shared with a healthcare professional.</div>}
   <div className="content">{loading&&<div className="loading-line"><span/> Loading your information…</div>}
    {page==='Overview'&&<Dashboard data={demoMode?overview:data} user={user} setPage={setPage} demoMode={demoMode}/>}
    {page==='Health check'&&<HealthCheck records={demoMode?demoData.healthChecks:(data||[])} demoMode={demoMode} updateDemo={updateDemo} notify={notify} refresh={load} serviceStatus={serviceStatus}/>}
    {page==='Wellness'&&<Wellness entries={demoMode?demoData.wellnessEntries:(data||[])} demoMode={demoMode} updateDemo={updateDemo} notify={notify} refresh={load}/>}
    {page==='Age guidance'&&<Guidance data={demoMode?pageDemoData():data||guides[user?.age_group]||guides['30-45']} user={user}/>}
    {page==="Women's health"&&<WomenHealth cycles={demoMode?pageDemoData():data} demoMode={demoMode} updateDemo={updateDemo} notify={notify} refresh={load} user={user}/>}
    {page==='Emergency'&&<Emergency contacts={demoMode?demoData.contacts:(data||[])} demoMode={demoMode} updateDemo={updateDemo} notify={notify} refresh={load} user={user}/>}
    {page==='AI assistant'&&<Assistant demoMode={demoMode} notify={notify}/>}
    {page==='My records'&&<Records data={demoMode?overview:data||{}} demoMode={demoMode} demoData={demoData} notify={notify}/>}
    {page==='Profile'&&<Profile user={user} demoMode={demoMode} notify={notify} serviceStatus={serviceStatus} onUpdate={u=>{setUser(u);if(demoMode)localStorage.setItem(USER_STORE,JSON.stringify(u));}}/>}
   </div>
   <footer className="footer"><span>© 2026 MediVision AI · Personal wellness prototype</span><span>Not a diagnostic or emergency-service platform</span></footer>
  </main>{toast&&<div className="toast"><CheckCircle2 size={16}/>{toast}</div>}
 </div>;
}

function Dashboard({data,user,setPage,demoMode}){
 const latest=data?.latest_wellness, recent=data?.recent_records||[];
 return <>
  <div className="hero"><div><span className="eyebrow">A LITTLE CARE, EVERY DAY</span><h2>Good morning, {user?.full_name?.split(' ')[0]||'there'}.</h2><p>Make room for small habits that support your everyday wellbeing.</p><div className="hero-actions"><Btn onClick={()=>setPage('Wellness')}>Daily check-in <ChevronRight size={16}/></Btn><button className="text-action" onClick={()=>setPage('Health check')}>Add a health note <ArrowRight size={15}/></button></div></div><div className="hero-art"><div className="hero-sun"/><HeartPulse size={63}/><span className="hero-art-label">Your wellbeing, one day at a time</span></div></div>
  <div className="section-top"><div><h2>Your overview</h2><p>A snapshot of information in your wellness space.</p></div><span className="soft-tag"><span className="status-dot"/>{demoMode?'Sample activity':'Your account data'}</span></div>
  <div className="stat-grid"><Stat icon={Brain} label="Wellness check-ins" value={data?.wellness_count??0} sub="Saved reflections"/><Stat icon={Stethoscope} label="Health notes" value={data?.diagnosis_count??0} sub="Your own entries"/><Stat icon={HeartPulse} label="Latest stress index" value={latest?latest.stress_score+'/100':'—'} sub={latest?latest.mood+' · '+latest.sleep_hours+'h sleep':'Add a check-in'}/><Stat icon={CalendarDays} label="Cycle tracking" value={data?.cycle_tracking_enabled?'Enabled':'Optional'} sub={data?.cycle_tracking_enabled?(data?.cycle_count||0)+' entries':'Private opt-in module'}/></div>
  <div className="dashboard-grid"><Panel title="Your recent health notes" subtitle="Information you have chosen to save" action={<button className="text-action" onClick={()=>setPage('My records')}>View all <ArrowRight size={15}/></button>}>{recent.length?recent.slice(0,3).map(r=><div className="record-line" key={r.id}><div className="record-symbol"><FileText size={17}/></div><div className="record-main"><b>{r.symptoms}</b><small>{dateLabel(r.created_at)} · {r.severity}</small></div><ChevronRight size={16}/></div>):<Empty>Your health notes will appear here after you add one.</Empty>}</Panel>
   <Panel title="Your wellness trend" subtitle="A simple view of recent self-reported check-ins"><div className="trend-summary"><div><b>{latest?latest.stress_score+'/100':'No score yet'}</b><small>Latest illustrative index</small></div><div className="trend-chart"><SparkLine values={demoMode?[5,51,19]:[22,34,19]}/></div></div><Notice>Not a validated mental-health score. Use this only as a personal reflection aid.</Notice><Btn kind="soft" onClick={()=>setPage('Wellness')}>Open wellness tracker <ArrowRight size={15}/></Btn></Panel></div>
  <div className="section-top"><div><h2>Explore your wellness space</h2><p>Choose a module. Each section includes examples to help you get started.</p></div></div>
  <div className="feature-grid">{[[Stethoscope,'Health check','Record symptoms and organise a health note.','Health check','mint'],[Brain,'Mind & mood','Reflect on sleep, mood and stress patterns.','Wellness','lilac'],[Activity,'Age-based guidance','Explore general everyday movement ideas.','Age guidance','peach'],[HeartPulse,"Women's health",'Optional private cycle tracking and awareness.',"Women's health",'blue'],[MessageCircle,'AI health assistant','Ask general questions and explore sources.','AI assistant','lilac'],[ShieldAlert,'Emergency preparation','Save contacts and review safety information.','Emergency','peach']].map(([Icon,title,desc,target,tint])=><button className="feature-card" key={title} onClick={()=>setPage(target)}><div className={'feature-icon '+tint}><Icon size={20}/></div><b>{title}</b><small>{desc}</small><span className="feature-arrow"><ArrowRight size={16}/></span></button>)}</div>
  <Notice tone="warning">MediVision AI is an educational prototype. It does not diagnose, prescribe, interpret uploaded medical images, or contact emergency services.</Notice>
 </>;
}

function HealthCheck({records,demoMode,updateDemo,notify,refresh,serviceStatus}){
 const [symptoms,S]=useState(''),[category,C]=useState('symptom-check'),[file,F]=useState(null),[result,R]=useState(null),[busy,B]=useState(false);
 const examples=['Example: I have had a mild headache since this morning. I want to record when it started.','Example: My neck feels stiff after a long day at my desk.','Example: I want to save a note about a recent check-up report.'];
 const uploadsAvailable=demoMode||serviceStatus?.malware_scanning==='configured';
 async function submit(e){e.preventDefault();B(true);R(null);try{
  if(demoMode){const row={id:makeId(),symptoms:symptoms.trim(),category,severity:'Needs review',guidance:'Demo record saved for organisation only. This application does not identify a disease or determine clinical severity. Discuss persistent or concerning symptoms with a qualified healthcare professional.',attachment_name:file?.name||null,created_at:new Date().toISOString()};updateDemo(d=>({...d,healthChecks:[row,...d.healthChecks]}));R({...row,medical_notice:file?'File name recorded in this browser demo; no image analysis is performed.':'No image analysis is performed.'});S('');F(null);notify('Demo health note saved in this browser');}
  else{const f=new FormData();f.append('symptoms',symptoms);f.append('category',category);if(file)f.append('file',file);const res=await api('/api/diagnosis',{method:'POST',body:f});R(res);S('');F(null);notify('Health note saved');refresh();}
 }catch(e){notify(e.message);}finally{B(false);}}
 return <div className="two-col"><Panel title="Start a health check" subtitle="Record what you are experiencing or organise a health-related note"><form onSubmit={submit}>
  <Field label="What would you like to record?" hint="Choose the entry type. Uploading a file does not trigger automated image interpretation."><select value={category} onChange={e=>C(e.target.value)}><option value="symptom-check">Symptoms or general concern</option><option value="skin-image">Skin image (record only)</option><option value="xray">X-ray / scan (record only)</option><option value="report">Medical report note</option></select></Field>
  <Field label="Describe your symptoms or question" hint="Include when it started, how long it has lasted, what changes it, and anything else relevant."><textarea required minLength={3} maxLength={3000} value={symptoms} onChange={e=>S(e.target.value)} placeholder="Start typing your own description…"/></Field>
  <div className="field"><span className="field-label">Example descriptions</span><Suggestions items={['Mild headache example','Desk-related stiffness example','Report note example']} onPick={v=>S(examples[['Mild headache example','Desk-related stiffness example','Report note example'].indexOf(v)])}/></div>
  {!uploadsAvailable&&!demoMode&&<Notice tone="warning">Secure file scanning is not active yet, so attachments are temporarily disabled. You can still save a text health note. This prevents files being stored before a malware scan.</Notice>}
  <Field label="Attach image or PDF (optional)" hint={uploadsAvailable?'PNG, JPG, WEBP or PDF, up to 8 MB. Files are scanned before storage and are never diagnosed.':'Attachments will become available after the private malware-scanning service is configured.'}><input type="file" accept=".png,.jpg,.jpeg,.webp,.pdf" disabled={!uploadsAvailable} onChange={e=>F(e.target.files?.[0]||null)}/>{file&&<span className="file-picked">{file.name}</span>}</Field><Btn disabled={busy}>{busy?'Saving…':'Save health note'} <ChevronRight size={16}/></Btn>
 </form>{result&&<div className="result-card"><span className="soft-tag">{result.severity}</span><h3>Suggested next step</h3><p>{result.guidance}</p><small>{result.medical_notice}</small></div>}<div className="section-divider"/><h3>Recent entries</h3>{records.length?records.slice(0,4).map(r=><div className="record-line" key={r.id}><div className="record-symbol"><FileText size={17}/></div><div className="record-main"><b>{r.symptoms}</b><small>{dateLabel(r.created_at)} · {r.severity}{r.attachment_name?' · '+r.attachment_name:''}</small></div>{!demoMode&&r.attachment_name&&<button type="button" className="text-action" onClick={()=>downloadAttachment(r.id)}><Download size={14}/> Download</button>}</div>):<Empty>Save your first note to see it here.</Empty>}</Panel>
  <div className="stack"><Panel title="How to write a useful note" subtitle="A quick structure you can follow"><div className="guide-steps">{[['1','What happened?','Describe the main symptom in your own words.'],['2','When did it start?','Mention the date, time and whether it comes and goes.'],['3','What else is relevant?','Add triggers, existing care or questions for a clinician.']].map(x=><div key={x[0]}><span>{x[0]}</span><div><b>{x[1]}</b><small>{x[2]}</small></div></div>)}</div></Panel><Panel title="Important safety note"><Notice tone="warning">This feature records information and provides general safety wording only. It does not diagnose disease, classify medical images, or replace a clinician.</Notice><p className="muted">For severe breathing difficulty, chest pain, stroke-like symptoms, severe bleeding or loss of consciousness, seek emergency help now.</p></Panel></div>
 </div>;
}

function Wellness({entries,demoMode,updateDemo,notify,refresh}){
 const [mood,M]=useState('Normal'),[sleep,S]=useState('7'),[note,N]=useState(''),[saved,V]=useState(null),[breathing,Q]=useState(false);
 async function submit(e){e.preventDefault();try{
  if(demoMode){const moodFactor={Happy:5,Normal:15,Stressed:35,Low:40,Anxious:38}[mood]||15;const sleepFactor=Math.max(0,Math.min(40,Math.round(Math.abs(8-Number(sleep))*8)));const row={id:makeId(),mood,sleep_hours:Number(sleep),stress_score:Math.min(100,moodFactor+sleepFactor),note,created_at:new Date().toISOString(),suggestion:'Try a short grounding or breathing exercise. If distress is persistent or overwhelming, consider speaking with a qualified mental-health professional.'};updateDemo(d=>({...d,wellnessEntries:[row,...d.wellnessEntries]}));V(row);N('');notify('Check-in saved in this browser demo');}
  else{const r=await api('/api/wellness',{method:'POST',body:JSON.stringify({mood,sleep_hours:Number(sleep),note})});V(r);N('');notify('Daily check-in saved');refresh();}
 }catch(e){notify(e.message);}}
 const scores=[...entries].slice(0,7).reverse().map(x=>x.stress_score);
 return <div className="two-col"><div className="stack"><Panel title="How are you feeling today?" subtitle="A small moment to check in with yourself"><form onSubmit={submit}>
  <Field label="Choose a mood" hint="Pick the option that best describes how you feel right now."><div className="mood-grid">{[['Happy','☀️'],['Normal','🌿'],['Stressed','🌧️'],['Low','🌙'],['Anxious','〰️']].map(([m,emoji])=><button type="button" key={m} className={'mood-option '+(mood===m?'selected':'')} onClick={()=>M(m)}><span>{emoji}</span>{m}</button>)}</div></Field>
  <Field label="Hours of sleep last night" hint="Use a half-hour value if that is easier to estimate."><input type="number" min="0" max="24" step=".5" value={sleep} onChange={e=>S(e.target.value)}/></Field>
  <Field label="Anything you want to note? (optional)" hint="You could mention workload, movement, rest, or something positive from your day."><textarea value={note} onChange={e=>N(e.target.value)} placeholder="A few words about your day…"/></Field><Suggestions items={['Busy workday','Took a walk','Restful evening']} onPick={v=>N(n=>n?(n+' · '+v):v)}/><Btn>Save daily check-in <ChevronRight size={16}/></Btn>
 </form>{saved&&<div className="result-card"><h3>Your illustrative stress index: {saved.stress_score}/100</h3><div className="meter"><span style={{width:saved.stress_score+'%'}}/></div><p>{saved.suggestion}</p><small>This simple calculation is not a validated mental-health assessment or diagnosis.</small></div>}</Panel>
 <Panel title="Your recent check-ins" subtitle="Patterns from your own entries">{entries.length?entries.slice(0,6).map(e=><div className="record-line" key={e.id}><div className="record-symbol"><Brain size={17}/></div><div className="record-main"><b>{e.mood} · {e.sleep_hours} hours sleep</b><small>{dateLabel(e.created_at)}{e.note?' · '+e.note:''}</small></div><span className="score-pill">{e.stress_score}/100</span></div>):<Empty>Your check-ins will appear here after you save one.</Empty>}</Panel></div>
 <div className="stack"><Panel title="Your recent pattern" subtitle="An illustrative trend, not a clinical assessment"><div className="chart-box"><div className="chart-heading"><b>{entries.length?entries[0].stress_score+'/100':'—'}</b><small>Most recent index</small></div><SparkLine values={scores.length?scores:[12,18,14]}/><div className="chart-axis"><span>Older</span><span>Recent</span></div></div><Notice>Scores are calculated from self-reported mood and sleep in this prototype. Do not use them to assess a mental-health condition.</Notice></Panel>
 <Panel title="A moment to breathe" subtitle="A gentle optional grounding prompt"><div className={'breath-orb '+(breathing?'active':'')}><Wind size={29}/><b>{breathing?'Breathe slowly':'Pause for a moment'}</b><small>{breathing?'Inhale gently · Exhale comfortably':'Start when you feel ready'}</small></div><Btn kind="soft" onClick={()=>Q(v=>!v)}>{breathing?'Pause exercise':'Start breathing prompt'}</Btn><p className="muted">Try a comfortable slow inhale and a longer easy exhale. Stop if you feel dizzy or uncomfortable.</p></Panel></div></div>;
}

function Guidance({data,user}){
 const [done,D]=useState(0);const g=data?.items?data:(guides[user?.age_group]||guides['30-45']);const routine=g.routine||guides[user?.age_group||'30-45'].routine;
 return <div className="two-col"><div className="stack"><Panel title={g.title||'Everyday movement'} subtitle={'General ideas for age group '+(user?.age_group||'30-45')}><Notice>These are general wellness ideas, not individual exercise prescriptions or a guarantee that an activity is safe for you.</Notice><div className="guide-list">{g.items.map((x,i)=><div className="guide-item" key={i}><CheckCircle2 size={19}/><p>{x}</p></div>)}</div></Panel>
 <Panel title="Build a gentle routine" subtitle="Tap each step as you complete it"><div className="routine-list">{routine.map((x,i)=><button className={'routine-item '+(done>i?'done':'')} onClick={()=>D(n=>n===i+1?i:i+1)} key={i}><span>{done>i?<CheckCircle2 size={18}/>:(i+1)}</span><b>{x}</b><small>{done>i?'Marked complete':'Tap to mark complete'}</small></button>)}</div><div className="progress-track"><span style={{width:(done/routine.length*100)+'%'}}/></div><small className="muted">{done} of {routine.length} steps marked complete · This is a checklist, not a performance score.</small></Panel></div>
 <div className="stack"><Panel title="Is this exercise right for me?" subtitle="A few checks before you begin"><ul className="simple-list"><li>Choose an activity that feels comfortable and manageable.</li><li>Start gently and increase duration gradually.</li><li>Stop if you experience chest pain, dizziness, unusual breathlessness or pain.</li><li>Ask a clinician about activity changes if you have a health condition, injury or new symptoms.</li></ul></Panel><Panel title="What would you like to improve?"><div className="goal-chips"><span>Sleep</span><span>Mobility</span><span>Daily movement</span><span>Stress breaks</span></div><p className="muted">Update your wellness goal in Profile to keep preferences together.</p></Panel></div></div>;
}

function WomenHealth({cycles,demoMode,updateDemo,notify,refresh,user}){
 const [date,D]=useState(''),[length,L]=useState('28'),[notes,N]=useState(''),[symptom,S]=useState(''),[tab,T]=useState('tracker');
 if(cycles?.locked||!user?.women_health_opt_in)return <Panel title="Optional women's health space" subtitle="Private access is off for this profile"><Notice>This section is optional. Enable it in Profile only if you choose to use these tools. Do not enter information you do not want stored.</Notice><p className="muted">This module provides private tracking and general awareness only; it does not diagnose PCOS, predict fertility, or provide pregnancy care.</p></Panel>;
 async function add(e){e.preventDefault();try{if(demoMode){const row={id:makeId(),start_date:date,cycle_length:Number(length),notes:notes+(symptom?' · '+symptom:''),created_at:new Date().toISOString()};updateDemo(d=>({...d,cycleEntries:[row,...d.cycleEntries]}));}else await api('/api/womens-health/cycles',{method:'POST',body:JSON.stringify({start_date:date,cycle_length:Number(length),notes:notes+(symptom?' · '+symptom:'')})});D('');N('');S('');notify('Cycle entry saved');refresh();}catch(e){notify(e.message);}}
 return <div className="two-col"><div className="stack"><Panel title="Cycle tracking" subtitle="Record dates and notice your own patterns"><div className="tab-row"><button className={tab==='tracker'?'active':''} onClick={()=>T('tracker')}>Cycle log</button><button className={tab==='awareness'?'active':''} onClick={()=>T('awareness')}>Awareness</button></div>
 {tab==='tracker'?<><form onSubmit={add}><Field label="Period start date" hint="Enter a date you want to record; cycle length can vary."><input type="date" required value={date} onChange={e=>D(e.target.value)}/></Field><Field label="Typical cycle length (days)" hint="An estimate only; patterns differ between people."><input type="number" min="15" max="60" value={length} onChange={e=>L(e.target.value)}/></Field><Field label="Symptom or note (optional)"><select value={symptom} onChange={e=>S(e.target.value)}><option value="">Choose a note</option><option>Cramps</option><option>Headache</option><option>Fatigue</option><option>No symptoms noted</option><option>Prefer not to say</option></select></Field><Field label="Additional note (optional)"><textarea value={notes} onChange={e=>N(e.target.value)} placeholder="Anything you want to remember…"/></Field><Btn>Save cycle entry</Btn></form><div className="section-divider"/><h3>Recorded entries</h3>{cycles?.length?cycles.map(c=><div className="record-line" key={c.id}><div className="record-symbol"><CalendarDays size={17}/></div><div className="record-main"><b>{c.start_date} · {c.cycle_length} day cycle</b><small>{c.notes||'No additional note'}</small></div></div>):<Empty>No cycle entries yet.</Empty>}</>:<div className="awareness-list"><article><b>Cycle patterns</b><p>Tracking dates and symptoms can help you notice your own patterns over time. Cycle length can vary.</p></article><article><b>PCOS awareness</b><p>Irregular cycles, acne or excess hair can have several causes. An app cannot diagnose PCOS; a clinician can assess symptoms and decide whether tests are needed.</p></article><article><b>Pregnancy wellness</b><p>For pregnancy-specific advice, speak with an obstetric professional. Seek urgent care for concerning symptoms.</p></article></div>}</Panel></div>
 <div className="stack"><Panel title="Privacy first"><Notice>Women's health information can be sensitive. This module is opt-in and should be used only when you are comfortable saving these entries.</Notice><p className="muted">{demoMode?'In demo mode, entries stay in this browser.':'In account mode, entries are linked to your account on the configured backend.'}</p></Panel><Panel title="When to seek professional advice"><ul className="simple-list"><li>Severe pain or very heavy bleeding.</li><li>Significant or persistent changes in your usual pattern.</li><li>Concerns about PCOS or other symptoms.</li><li>Pregnancy-related questions or symptoms.</li></ul></Panel></div></div>;
}

function Emergency({contacts,demoMode,updateDemo,notify,refresh,user}){
 const [name,N]=useState(''),[relationship,R]=useState(''),[phone,P]=useState(''),[prepared,Q]=useState(false);
 async function add(e){e.preventDefault();try{if(demoMode)updateDemo(d=>({...d,contacts:[{id:makeId(),name,relationship,phone},...d.contacts]}));else await api('/api/emergency/contacts',{method:'POST',body:JSON.stringify({name,relationship,phone})});N('');R('');P('');notify('Emergency contact saved');refresh();}catch(e){notify(e.message);}}
 async function del(id){try{if(demoMode)updateDemo(d=>({...d,contacts:d.contacts.filter(c=>c.id!==id)}));else await api('/api/emergency/contacts/'+id,{method:'DELETE'});notify('Contact removed');refresh();}catch(e){notify(e.message);}}
 const summary='MEDIVISION PERSONAL SAFETY SUMMARY\nName: '+(user?.full_name||'Not set')+'\nAge group: '+(user?.age_group||'Not set')+'\nEmergency contacts: '+((contacts||[]).map(c=>c.name+' ('+c.relationship+') '+c.phone).join('; ')||'No contacts saved')+'\nVerify all details before sharing. Nothing is automatically sent.';
 return <div className="two-col"><div className="stack"><Panel title="Emergency help" subtitle="Preparedness information only"><div className="emergency-banner"><ShieldAlert size={28}/><div><b>Need urgent help?</b><p>If someone may be in immediate danger, contact local emergency services directly. Do not wait for this website.</p></div></div><a className="emergency-call" href="tel:112"><Phone size={18}/> Call 112 in India</a><small className="field-hint">Opens your device's phone app. MediVision does not place calls or dispatch emergency services.</small><div className="section-divider"/><button className="text-action" onClick={()=>Q(v=>!v)}>{prepared?'Hide preparedness checklist':'Show preparedness checklist'} <ChevronRight size={15}/></button>{prepared&&<ul className="simple-list"><li>Keep emergency numbers accessible.</li><li>Tell a trusted person where you keep important medical information.</li><li>Carry current medication and allergy information where appropriate.</li><li>Verify contacts and details regularly.</li></ul>}</Panel>
 <Panel title="Your emergency contacts" subtitle="Save up to five people you may need to reach"><form onSubmit={add}><Field label="Contact name"><input required minLength="2" value={name} onChange={e=>N(e.target.value)} placeholder="e.g. Ananya Sharma"/></Field><Field label="Relationship"><input required value={relationship} onChange={e=>R(e.target.value)} placeholder="e.g. Parent, friend, partner"/></Field><Field label="Phone number"><input required minLength="7" value={phone} onChange={e=>P(e.target.value)} placeholder="Enter a contact number"/></Field><Suggestions items={['Parent','Friend','Partner']} onPick={R}/><Btn><Plus size={16}/> Add contact</Btn></form>{(contacts||[]).map(c=><div className="record-line" key={c.id}><div className="record-symbol"><Phone size={16}/></div><div className="record-main"><b>{c.name}</b><small>{c.relationship} · {c.phone}</small></div><button className="icon-button" onClick={()=>del(c.id)} aria-label="Delete contact"><Trash2 size={16}/></button></div>)}{!contacts?.length&&<Empty>Add a trusted contact to build your personal list.</Empty>}</Panel></div>
 <div className="stack"><Panel title="Personal safety card" subtitle="Create a small text summary for your own records"><p className="muted">Review details before sharing. This summary is not verified and is not automatically sent to anyone.</p><div className="safety-card"><b>{user?.full_name||'Your name'}</b><small>{user?.age_group||'Age group not set'} · Health goal: {user?.health_goal||'Not set'}</small><p>{contacts?.length||0} emergency contact(s) saved</p></div><Btn kind="soft" onClick={()=>{const blob=new Blob([summary],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='medivision-safety-card.txt';a.click();URL.revokeObjectURL(url);notify('Safety card downloaded');}}><Download size={16}/> Download safety card</Btn></Panel><Notice tone="warning">No SOS dispatch, live location sharing, hospital availability or ambulance booking is active in this prototype.</Notice></div></div>;
}

function demoAnswer(q){
 const s=q.toLowerCase();
 if(/emergency|urgent|chest pain|breath|stroke/.test(s))return {answer:'If you may be experiencing a life-threatening emergency — such as severe difficulty breathing, chest pain, suspected stroke, severe bleeding or loss of consciousness — contact local emergency services immediately. Do not wait for an online assistant. In India, 112 is the pan-India emergency number. This assistant cannot call for help.',sources:[{title:'NHS: When to call 999',url:'https://www.nhs.uk/nhs-services/urgent-and-emergency-care-services/when-to-call-999/'},{title:'India Emergency Response Support System',url:'https://112.gov.in/'}]};
 if(/sleep|insomnia|tired/.test(s))return {answer:'A consistent sleep and wake schedule, a calming wind-down routine and a comfortable sleep environment may support better sleep. Sleep needs vary by age and individual. If sleep problems continue or affect daily life, consider discussing them with a healthcare professional.',sources:[{title:'CDC: About Sleep',url:'https://www.cdc.gov/sleep/about/index.html'}]};
 if(/stress|anxious|anxiety|grounding|mood/.test(s))return {answer:'A simple grounding practice is to notice your feet on the floor, slowly name a few things you can see and hear, and return attention to the present moment. Keep the exercise comfortable and stop if it makes you feel worse. If distress is persistent or overwhelming, seek support from a qualified mental-health professional.',sources:[{title:'WHO: Doing What Matters in Times of Stress',url:'https://www.who.int/publications/i/item/9789240003927'}]};
 if(/exercise|fitness|walk|workout|desk/.test(s))return {answer:'Regular physical activity can support health. Choose activities that match your current ability, begin gradually and make recovery part of the routine. Stop if you experience chest pain, dizziness, unusual breathlessness or pain. Ask a clinician about activity changes if you have a health condition or new symptoms.',sources:[{title:'WHO: Physical activity',url:'https://www.who.int/news-room/fact-sheets/detail/physical-activity'}]};
 if(/period|cycle|pcos|menstrual/.test(s))return {answer:'Menstrual cycles vary. Recording period dates and symptoms can help you notice your own patterns. PCOS can involve different symptoms, but no single symptom or app-based questionnaire can confirm it. Discuss significant changes or concerns with a qualified healthcare professional.',sources:[{title:'NHS: Periods',url:'https://www.nhs.uk/conditions/periods/'},{title:'NHS: PCOS',url:'https://www.nhs.uk/conditions/polycystic-ovary-syndrome-pcos/'}]};
 if(/skin|mole|rash|image|x-ray|xray/.test(s))return {answer:'This MediVision prototype does not interpret medical images. New, changing, bleeding or unusual skin lesions should be assessed by a healthcare professional. An online image review cannot rule out serious disease. For scans and reports, ask the clinician who ordered the test to explain the findings.',sources:[{title:'NHS: Moles',url:'https://www.nhs.uk/conditions/moles/'}]};
 return {answer:'I can help with general wellness education, but I cannot diagnose, prescribe or determine whether a condition is present. Try asking about sleep routines, stress grounding, everyday physical activity, menstrual health awareness or when to seek urgent care. For personal medical advice, speak with a qualified clinician.',sources:[]};
}
function Assistant({demoMode,notify}){
 const [message,M]=useState(''),[history,H]=useState([]),[busy,B]=useState(false);
 async function send(e,override){e?.preventDefault();const q=(override||message).trim();if(!q||busy)return;H(h=>[...h,{role:'you',text:q}]);M('');B(true);try{const r=demoMode?demoAnswer(q):await api('/api/assistant/chat',{method:'POST',body:JSON.stringify({message:q})});H(h=>[...h,{role:'assistant',text:r.answer,sources:r.sources||[]}]);}catch(err){H(h=>[...h,{role:'assistant',text:err.message}]);notify('Assistant request failed');}finally{B(false);}}
 return <div className="two-col"><Panel title="MediVision health assistant" subtitle="General health education · References shown where available"><div className="chat-log">{history.length===0&&<div className="assistant-welcome"><div className="assistant-avatar"><Sparkles/></div><b>Hello! What would you like to understand?</b><p>I can explain general wellness topics in plain language and share references. I cannot diagnose or prescribe.</p></div>}{history.map((m,i)=><div className={'bubble '+m.role} key={i}><b>{m.role==='you'?'You':'MediVision assistant'}</b><p>{m.text}</p>{m.sources?.map((s,j)=><a key={j} href={s.url} target="_blank" rel="noreferrer">{s.title} ↗</a>)}</div>)}{busy&&<div className="typing">MediVision is preparing a response…</div>}</div>
  {history.length===0&&<div className="prompt-list"><span className="field-label">Try one of these prompts</span>{prompts.map(p=><button key={p} onClick={()=>send(null,p)}>{p}<ArrowRight size={14}/></button>)}</div>}
  <form className="chat-form" onSubmit={send}><input value={message} onChange={e=>M(e.target.value)} placeholder="Ask a general wellness question…"/><Btn disabled={busy}><Send size={16}/></Btn></form></Panel>
 <div className="stack"><Panel title="What this assistant can do"><ul className="simple-list"><li>Explain general health information in simpler language.</li><li>Suggest questions you could ask a qualified clinician.</li><li>Point to curated public health references.</li><li>Say when its information is not enough.</li></ul></Panel><Notice tone="warning">Do not use this assistant for emergencies, diagnosis, medication decisions or treatment instructions. It does not replace a clinician.</Notice></div></div>;
}

function Records({data,demoMode,demoData,notify}){
 const records=demoMode?demoData.healthChecks:(data?.recent_records||[]),wellness=demoMode?demoData.wellnessEntries:[];
 async function download(){
  try{
   let text;
   if(!demoMode){text=await api('/api/reports/summary.txt');}
   else{
    const lines=['MEDIVISION AI — PERSONAL WELLNESS SUMMARY','','DEMO DATA — FICTIONAL SAMPLE INFORMATION','Generated: '+new Date().toLocaleString(),'','HEALTH NOTES',...records.map(r=>(r.created_at||'')+' | '+r.severity+' | '+r.symptoms),'','WELLNESS CHECK-INS',...wellness.map(w=>w.created_at+' | '+w.mood+' | sleep '+w.sleep_hours+'h | illustrative index '+w.stress_score+'/100'),'','This is a user-entered wellness summary, not a formal medical record or diagnosis.'];
    text=lines.join('\\n');
   }
   const blob=new Blob([text],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='medivision-wellness-summary.txt';a.click();URL.revokeObjectURL(url);notify('Summary downloaded');
  }catch(e){notify(e.message);}
 }
 return <div className="stack"><Panel title="Your wellness history" subtitle="A personal summary of information stored in your wellness space" action={<Btn kind="soft" onClick={download}><Download size={15}/> Download summary</Btn>}><Notice>This is a personal wellness summary of information entered into the application. It is not a formal medical record.</Notice><h3>Recent health notes</h3>{records.length?records.map(r=><div className="record-line" key={r.id}><div className="record-symbol"><ClipboardList size={17}/></div><div className="record-main"><b>{r.symptoms}</b><small>{dateLabel(r.created_at)} · {r.category||'Health note'}</small></div><span className="soft-tag">{r.severity}</span></div>):<Empty>Your health notes will appear here after you save one.</Empty>}{demoMode&&<><div className="section-divider"/><h3>Wellness check-ins</h3>{wellness.length?wellness.map(w=><div className="record-line" key={w.id}><div className="record-symbol"><Brain size={17}/></div><div className="record-main"><b>{w.mood} · {w.sleep_hours}h sleep</b><small>{dateLabel(w.created_at)}{w.note?' · '+w.note:''}</small></div><span className="score-pill">{w.stress_score}/100</span></div>):<Empty>No wellness check-ins yet.</Empty>}</>}</Panel></div>;
}

function Profile({user,demoMode,notify,onUpdate,serviceStatus}){
 const [form,F]=useState({...user});useEffect(()=>F({...user}),[user]);const change=(k,v)=>F(f=>({...f,[k]:v}));
 async function deleteAccount(){if(demoMode)return;if(!window.confirm('Permanently delete your MediVision account, wellness entries, health notes, cycle records, emergency contacts and private attachments? This cannot be undone.'))return;try{await api('/api/auth/me',{method:'DELETE'});clearSession();window.location.reload();}catch(e){notify(e.message);}}
 async function save(e){e.preventDefault();try{if(demoMode){onUpdate(form);notify('Demo profile updated in this browser');}else{const r=await api('/api/profile',{method:'PUT',body:JSON.stringify(form)});onUpdate(r);notify('Profile updated');}}catch(e){notify(e.message);}}
 return <div className="two-col"><Panel title="Your profile" subtitle="Update your details and wellness preferences"><form onSubmit={save}><Field label="Full name"><input required minLength="2" value={form.full_name||''} onChange={e=>change('full_name',e.target.value)}/></Field><Field label="Age (optional)"><input type="number" min="16" max="120" value={form.age||''} onChange={e=>change('age',e.target.value?Number(e.target.value):null)}/></Field><Field label="Age group"><select value={form.age_group||'30-45'} onChange={e=>change('age_group',e.target.value)}><option>16-30</option><option>30-45</option><option>45+</option></select></Field><Field label="Gender (optional)"><select value={form.gender||''} onChange={e=>change('gender',e.target.value)}><option value="">Prefer not to say</option><option>Female</option><option>Male</option><option>Non-binary</option><option>Self describe</option></select></Field><Field label="Primary wellness goal"><select value={form.health_goal||'prevent'} onChange={e=>change('health_goal',e.target.value)}><option value="prevent">Preventive wellness</option><option value="fitness">Improve fitness</option><option value="stress">Stress reduction</option><option value="senior">Senior care</option></select></Field><label className="check"><input type="checkbox" checked={!!form.women_health_opt_in} onChange={e=>change('women_health_opt_in',e.target.checked)}/> Enable optional women's health tools</label><Btn>Save profile</Btn></form></Panel>
 <div className="stack"><Panel title="Connected services" subtitle="Live configuration status for account and file safety">
  {!demoMode?<><div className="record-line"><div className="record-main"><b>Attachment malware scanning</b><small>Files can be stored only after ClamAV confirms they are clean.</small></div><span className="soft-tag">{serviceStatus?.malware_scanning==='configured'?'Configured':'Not configured'}</span></div><div className="record-line"><div className="record-main"><b>Password-reset email</b><small>Secure account recovery requires the verified email provider.</small></div><span className="soft-tag">{serviceStatus?.password_reset_email==='configured'?'Configured':'Not configured'}</span></div><Notice tone="warning">An unconfigured service remains unavailable. Never upload real health documents until the required security and privacy reviews are completed.</Notice></>:<Notice tone="info">The demo uses fictional local data. Live service connections are checked when you use your account.</Notice>}</Panel><Panel title="Privacy and data"><p className="muted">You control the information saved to your account. You can permanently remove your account and its associated records.</p>{!demoMode&&<Btn kind="danger" type="button" onClick={deleteAccount}>Delete account and all records</Btn>}<Notice tone="warning">{demoMode?'The demo profile and entries are kept in this browser only. Reset demo data from the sidebar at any time.':'Do not upload real patient information until independent security, privacy and operational reviews are complete.'}</Notice></Panel><Panel title="Privacy and demo information"><p className="muted">{demoMode?'The demo profile and entries are kept in this browser only. Reset demo data from the sidebar at any time.':'Your entries are associated with your account. Review deployment privacy and data retention before using real health information.'}</p><Notice tone="warning">Use synthetic data only until the application has a persistent database, production security review, and appropriate privacy and clinical governance.</Notice></Panel><Panel title="Personalisation tips"><ul className="simple-list"><li>Choose the age group that best fits the guidance section you want to explore.</li><li>Set a wellness goal to describe what matters to you.</li><li>Women's health tools stay off unless you explicitly enable them.</li></ul></Panel></div></div>;
}
